<!DOCTYPE html>
<html lang="tr">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Tourtime</title>
<link rel="stylesheet" href="assets/css/main.css" />
</head>
<body>
<header class="header">
    <div class="header__container">
        <a class="header__logo" href="#" aria-label="Tourtime Ana Sayfa"><img src="data:image/svg+xml;base64," alt="Tourtime"></a>
        <nav class="header__nav" aria-label="Ana menü">
            <a class="active" href="#">Ana Sayfa</a>
            <a href="#">Bizi Tanıyın</a>
            <a href="#">Turlar</a>
            <a href="#">Seyahat Rehberi</a>
            <a href="#">İletişim</a>
        </nav>
    </div>
</header>

<section class="hero" aria-label="Tourtime Slider">
    <div class="hero__track">
        <article class="hero__slide active" data-title="Türkiye’nin en özgürlükçü ve yenilikçi seyahati" style="background-image:url('data:image/webp;base64,');">
            <div class="hero__content">
                <h1 class="hero__title">Türkiye’nin en özgürlükçü<br>ve yenilikçi seyahati</h1>
                <img class="hero__line" src="data:image/png;base64," alt="">
            </div>
        </article>
        <article class="hero__slide" data-title="Yeni rotalar, özgür anılar" style="background-image:url('data:image/webp;base64,');">
            <div class="hero__content">
                <h2 class="hero__title">Yeni rotalar,<br>özgür anılar</h2>
                <img class="hero__line" src="data:image/png;base64," alt="">
            </div>
        </article>
    </div>
    <button class="hero__arrow hero__arrow--prev" type="button" aria-label="Önceki slide">‹</button>
    <button class="hero__arrow hero__arrow--next" type="button" aria-label="Sonraki slide">›</button>
    <div class="hero__dots" aria-label="Slider noktaları"></div>
</section>

<script type="text/javascript" src="assets/js/main.js"></script>
</body>
</html>